df=pd.read_csv('/app/benchmark/data.csv').sort_values('Year').reset_index(drop=True)
df['Decade']=(df['Year']//10)*10

def era(y):
    if y<=1959: return 'Golden Age (1934–1959)'
    if y<=1979: return 'Silver Age (1960–1979)'
    if y<=1999: return 'Modern Era (1980–1999)'
    return 'Contemporary Era (2000–2026)'
df['Era']=df['Year'].map(era)

unique_composers=df['Composer'].nunique()
unique_films=df['Film'].nunique()
max_wins=df['Composer'].value_counts().max()
top=df['Composer'].value_counts().rename_axis('Composer').reset_index(name='Wins')
repeat=0;seen=set()
for c in df['Composer']:
    if c in seen: repeat+=1
    else: seen.add(c)
repeat_rate=repeat/len(df)

by_dec=df.groupby('Decade').agg(Ceremonies=('Year','count'),UniqueWinners=('Composer','nunique')).reset_index()
by_dec['RepeatWins']=by_dec['Ceremonies']-by_dec['UniqueWinners']
by_dec['RepeatShare']=by_dec['RepeatWins']/by_dec['Ceremonies']
max_dec=by_dec.loc[by_dec['UniqueWinners'].idxmax()]

by_era=df.groupby('Era').agg(Ceremonies=('Year','count'),UniqueComposers=('Composer','nunique')).reset_index()
by_era['RepeatRate']=(by_era['Ceremonies']-by_era['UniqueComposers'])/by_era['Ceremonies']

# milestones
first_wins=df.drop_duplicates('Composer',keep='first')[['Year','Composer','Film']]
latest=df.iloc[-1]
# longest gap
lg=(None,-1,None,None)
for c,g in df.groupby('Composer'):
    ys=g['Year'].tolist()
    for a,b in zip(ys,ys[1:]):
        if b-a>lg[1]: lg=(c,b-a,a,b)
# consecutive streak
best=('None',1,None,None)
cur=1;start=df.iloc[0]['Year']
for i in range(1,len(df)):
    if df.iloc[i]['Composer']==df.iloc[i-1]['Composer']:
        cur+=1
    else:
        if cur>best[1]: best=(df.iloc[i-1]['Composer'],cur,start,df.iloc[i-1]['Year'])
        cur=1; start=df.iloc[i]['Year']
if cur>best[1]: best=(df.iloc[-1]['Composer'],cur,start,df.iloc[-1]['Year'])

# charts via plotly CDN
import json

def to_records(frame, cols):
    return frame[cols].to_dict(orient='records')

